namespace Scada.Api.Runtime;

public static partial class ContextualHelpCatalog
{
    private static string HelpExample(string name)
    {
        var assembly = typeof(ContextualHelpCatalog).Assembly;
        var resource = assembly.GetManifestResourceNames().Single(item => item.EndsWith($".HelpExamples.{name}.py", StringComparison.Ordinal));
        using var stream = assembly.GetManifestResourceStream(resource)!;
        using var reader = new StreamReader(stream);
        return reader.ReadToEnd().TrimEnd();
    }

    private static IEnumerable<ContextualHelpTopic> BuildScriptLearningGuides(string locale)
    {
        yield return LT(locale, "scripts.choose-scope", "scripts",
            Tx("Antes do código: escolha onde o Script executa", "Before coding: choose where the Script runs", "Antes del código: elija dónde se ejecuta el Script"),
            Tx("Server e Client Visual atendem tarefas diferentes e usam APIs diferentes.", "Server and Client Visual serve different tasks and use different APIs.", "Server y Client Visual atienden tareas distintas y usan APIs diferentes."),
            [
                LS(locale, "Comece pelo efeito desejado", "Start with the intended effect", "Empiece por el efecto deseado",
                    "Para uma regra que deve executar no servidor sem depender de uma tela aberta, escolha Server. Para reagir a um clique ou mudar a apresentação do objeto em uma tela aberta, escolha Client Visual. Escreva a intenção em uma frase, por exemplo: quando o operador apontar para este objeto, realçá-lo; ou a cada intervalo, calcular um valor a partir de TAGs declarados.",
                    "For a rule that must run on the server without an open screen, choose Server. To respond to a click or change an object's presentation on an open screen, choose Client Visual. Write the intent in one sentence, for example: highlight this object when the operator points at it; or calculate a value from declared TAGs at each interval.",
                    "Para una regla que deba ejecutarse en el servidor sin pantalla abierta, elija Server. Para responder a un clic o cambiar la presentación de un objeto abierto, elija Client Visual. Escriba la intención en una frase: resaltar este objeto al apuntarlo; o calcular un valor desde TAGs declarados en cada intervalo."),
                LS(locale, "Não misture as duas APIs", "Keep the two APIs distinct", "Distinga las dos APIs",
                    "Cada escopo oferece seu próprio conjunto de funções, chamado API. No Server, você chama diretamente funções como `read_tag` e `write_server_memory`. A sintaxe aceita é limitada; consulte o guia de sintaxe Server ao escrever o cálculo.\n\nNo Client Visual, as funções são importadas de `elite_scada`, como `tag_read` e `visual_property_write`. As chamadas que esperam resposta usam `async def` e `await`; o guia de exemplos Client Visual explica como escrevê-las.\n\nAntes de copiar um exemplo, confira o escopo indicado. Server pode produzir uma variável que a tela acompanha, mas não altera diretamente seu desenho.",
                    "Each scope provides its own set of functions, called an API. On Server, call functions such as `read_tag` and `write_server_memory` directly. Supported syntax is limited; use the Server syntax guide when writing the calculation.\n\nIn Client Visual, functions such as `tag_read` and `visual_property_write` are imported from `elite_scada`. Calls that wait for a response use `async def` and `await`; the Client Visual examples guide explains how to write them.\n\nBefore copying an example, check its stated scope. Server can produce a variable that a screen follows, but cannot directly change its drawing.",
                    "Cada alcance ofrece su propio conjunto de funciones, llamado API. En Server se llaman directamente funciones como `read_tag` y `write_server_memory`. La sintaxis admitida es limitada; consulte la guía de sintaxis Server al escribir el cálculo.\n\nEn Client Visual, funciones como `tag_read` y `visual_property_write` se importan de `elite_scada`. Las llamadas que esperan respuesta usan `async def` y `await`; la guía de ejemplos Client Visual explica cómo escribirlas.\n\nAntes de copiar un ejemplo, compruebe el alcance indicado. Server puede producir una variable que sigue la pantalla, pero no cambia directamente su dibujo."),
                LS(locale, "O código precisa de uma ligação", "Code needs a connection", "El código necesita una conexión",
                    "Criar uma função não faz com que ela execute. Configure um ponto de entrada: ele liga um evento ao nome exato da função, chamado handler. Declare também os TAGs e demais recursos usados como dependências. Código, evento e referências formam a configuração; confira os três antes de procurar um defeito de sintaxe.",
                    "Creating a function does not make it run. Configure an entry point: it connects an event to the exact function name, called the handler. Also declare TAGs and other resources as dependencies. Code, event and references make up the configuration; check all three before looking for a syntax defect.",
                    "Crear una función no hace que se ejecute. Configure un punto de entrada: conecta un evento al nombre exacto de función, llamado handler. Declare TAGs y otros recursos como dependencias. Código, evento y referencias forman la configuración; compruebe los tres antes de buscar un fallo de sintaxis.")
            ], "scripts.server-syntax", "scripts.triggers-dependencies", "scripts.server", "scripts.client-visual", "scripts.client-recipes");

        yield return LT(locale, "scripts.server-syntax", "scripts",
            Tx("Server Script: sintaxe explicada desde o início", "Server Script: syntax from the beginning", "Server Script: sintaxis desde el principio"),
            Tx("Aprenda a ler uma função, usar valores e escrever condições no subconjunto aceito pelo servidor.", "Learn to read a function, use values and write conditions in the server's supported subset.", "Aprenda a leer una función, usar valores y escribir condiciones en el subconjunto del servidor."),
            [
                LS(locale, "Leia este exemplo linha por linha", "Read this example line by line", "Lea este ejemplo línea por línea",
                    "O exemplo abaixo lê uma variável e arredonda o valor. Leia nesta ordem:\n\n1. `def on_timer():` cria a função chamada `on_timer`. Esse é o nome a selecionar como Handler na entrada do Script. Os parênteses vazios indicam que ela não recebe argumentos.\n2. Os dois-pontos abrem o bloco da função. As linhas com quatro espaços à esquerda pertencem a ele.\n3. `read_tag` lê o TAG declarado entre aspas. `current` guarda a leitura numa variável local, usada apenas nesta execução da função.\n4. `if` só executa o próximo bloco se a condição for verdadeira. `None` significa que não há valor; é diferente do número zero.\n5. `round(current, 2)` arredonda para duas casas. A última chamada guarda o resultado na memória do servidor declarada.\n\nAntes de testar, declare a leitura e o destino de memória e configure a entrada que chama `on_timer`. Criar a função não a faz executar sozinha.",
                    "The example below reads a variable and rounds its value. Read it in this order:\n\n1. `def on_timer():` creates a function named `on_timer`. Select that name as the Handler in the Script entry point. Empty parentheses mean it takes no arguments.\n2. The colon opens the function block. Lines with four spaces on the left belong to it.\n3. `read_tag` reads the declared TAG in quotes. `current` holds the reading in a local variable, used only during this function call.\n4. `if` runs the next block only when its condition is true. `None` means no value; it is different from zero.\n5. `round(current, 2)` rounds to two places. The last call stores the result in declared server memory.\n\nBefore testing, declare the reading and memory target and configure the entry point that calls `on_timer`. Creating the function does not make it run by itself.",
                    "El ejemplo siguiente lee una variable y redondea su valor. Léalo en este orden:\n\n1. `def on_timer():` crea la función `on_timer`. Seleccione ese nombre como Handler en la entrada del Script. Los paréntesis vacíos indican que no recibe argumentos.\n2. Los dos puntos abren el bloque. Las líneas con cuatro espacios a la izquierda pertenecen a la función.\n3. `read_tag` lee el TAG declarado entre comillas. `current` guarda la lectura en una variable local, utilizada solo durante esa llamada.\n4. `if` ejecuta el bloque siguiente si su condición es verdadera. `None` significa ausencia de valor; no es cero.\n5. `round(current, 2)` redondea a dos decimales. La última llamada guarda el resultado en memoria de servidor declarada.\n\nAntes de probar, declare lectura y destino de memoria y configure la entrada que llama a `on_timer`. Crear la función no hace que se ejecute sola.",
                    HelpExample("server-round")),
                LS(locale, "Valores, nomes e operadores", "Values, names and operators", "Valores, nombres y operadores",
                    "Use nomes que expliquem a leitura, como `current`. Maiúsculas fazem diferença: `current` e `Current` são variáveis distintas.\n\nPara guardar um valor, use `=`: `limit = 8` guarda 8 em `limit`. Para perguntar se dois valores são iguais, use `==`. `!=` significa diferente; `<`, `<=`, `>` e `>=` comparam números.\n\nEscreva decimais com ponto, como `12.5`. Use `+`, `-`, `*` e `/` para somar, subtrair, multiplicar e dividir. Texto fica entre aspas: `\"Running\"` é texto; `Running` sem aspas seria um nome de variável. `True` e `False` são os valores booleanos, isto é, verdadeiro e falso, escritos com inicial maiúscula.",
                    "Choose names that explain the reading, such as `current`. Case matters: `current` and `Current` are different variables.\n\nUse `=` to store a value: `limit = 8` stores 8 in `limit`. Use `==` to ask whether two values are equal. `!=` means different; `<`, `<=`, `>` and `>=` compare numbers.\n\nWrite decimals with a dot, such as `12.5`. Use `+`, `-`, `*` and `/` to add, subtract, multiply and divide. Put text in quotes: `\"Running\"` is text; unquoted `Running` would be a variable name. `True` and `False` are boolean values, meaning true and false, written with capital initials.",
                    "Elija nombres que expliquen la lectura, como `current`. Las mayúsculas importan: `current` y `Current` son variables distintas.\n\nUse `=` para guardar un valor: `limit = 8` guarda 8 en `limit`. Use `==` para preguntar si dos valores son iguales. `!=` significa diferente; `<`, `<=`, `>` y `>=` comparan números.\n\nEscriba decimales con punto, como `12.5`. Use `+`, `-`, `*` y `/` para sumar, restar, multiplicar y dividir. El texto lleva comillas: `\"Running\"` es texto; `Running` sin comillas sería una variable. `True` y `False` son los booleanos, verdadero y falso, escritos con inicial mayúscula."),
                LS(locale, "Trate ausência e divisão por zero", "Handle missing values and division by zero", "Trate ausencia y división por cero",
                    "Uma divisão precisa de duas verificações: as leituras existem e o divisor é diferente de zero. Faça uma verificação de cada vez, com um `if` dentro do outro, como no exemplo.\n\nNo Server, `and` e `or` avaliam todas as partes da expressão. Por isso, combinar as verificações numa única expressão não protege uma operação que pode falhar. Essa é uma diferença em relação ao Python comum.\n\nSe faltar dado, o exemplo não grava um novo resultado: a memória mantém o último valor. Mostre essa indisponibilidade separadamente na aplicação para que um valor antigo não pareça uma leitura atual.",
                    "A division needs two checks: the readings exist and the divisor is not zero. Check one thing at a time, with one `if` inside another, as in the example.\n\nOn Server, `and` and `or` evaluate every part of the expression. Combining checks into one expression therefore does not protect an operation that can fail. This differs from ordinary Python.\n\nIf data is missing, the example writes no new result: memory retains its last value. Show unavailability separately in the application so an old value does not look like a current reading.",
                    "Una división necesita dos comprobaciones: que existan las lecturas y que el divisor no sea cero. Compruebe una cosa por vez, con un `if` dentro de otro, como en el ejemplo.\n\nEn Server, `and` y `or` evalúan todas las partes de la expresión. Reunir las comprobaciones en una sola expresión no protege una operación que puede fallar. Es una diferencia respecto al Python habitual.\n\nSi faltan datos, el ejemplo no escribe un resultado nuevo: la memoria conserva el último valor. Muestre por separado la indisponibilidad para que un valor antiguo no parezca una lectura actual.",
                    HelpExample("server-ratio")),
                LS(locale, "O que este interpretador aceita", "What this interpreter supports", "Qué admite este intérprete",
                    "Use funções `def`, variáveis locais, `if/elif/else`, `return`, valores escalares, listas/dicionários literais e acesso por índice, comparações e chamadas posicionais às APIs e funções permitidas. Estão disponíveis `min`, `max`, `abs`, `round`, `int`, `float`, `bool`, `str` e `len`. Não use `import`, `for`, `while`, comprehensions, classes, `try/except`, `lambda`, f-strings, atributos ou argumentos nomeados. No nível principal, declare as funções; coloque as operações dentro delas. Essa restrição é do Server, não uma descrição geral de toda a linguagem Python.",
                    "Use `def` functions, local variables, `if/elif/else`, `return`, scalar values, literal lists/dictionaries and indexing, comparisons and positional calls to permitted functions/APIs. `min`, `max`, `abs`, `round`, `int`, `float`, `bool`, `str` and `len` are available. Do not use `import`, `for`, `while`, comprehensions, classes, `try/except`, `lambda`, f-strings, attributes or keyword arguments. At the top level declare functions; put operations inside them. This is a Server restriction, not a general description of Python.",
                    "Use funciones `def`, variables locales, `if/elif/else`, `return`, valores escalares, listas/diccionarios literales e índices, comparaciones y llamadas posicionales permitidas. Dispone de `min`, `max`, `abs`, `round`, `int`, `float`, `bool`, `str` y `len`. No use `import`, `for`, `while`, comprehensions, clases, `try/except`, `lambda`, f-strings, atributos ni argumentos nombrados. Declare funciones en el nivel principal y ponga operaciones dentro. Es una restricción de Server, no de todo Python.")
            ], "scripts.choose-scope", "scripts.triggers-dependencies", "scripts.server-recipes", "scripts.server");

        yield return LT(locale, "scripts.triggers-dependencies", "scripts",
            Tx("Ligar função, evento e dependências", "Connect function, event and dependencies", "Vincular función, evento y dependencias"),
            Tx("Preencha os campos que fazem o código executar no momento certo e acessar os recursos corretos.", "Fill in the fields that make code run at the right time and access the right resources.", "Complete los campos que ejecutan el código en el momento y con los recursos correctos."),
            [
                LS(locale, "Nome e escopo do Script", "Script name and scope", "Nombre y alcance del Script",
                    "Dê ao Script um nome de exibição que explique sua tarefa. A chave é sua identificação no projeto; não é o nome da função.\n\nEm escopo, escolha onde ele trabalha: Server no servidor, Client Visual na tela aberta. Essa escolha muda as funções e eventos disponíveis.\n\nHandler é a função que será chamada. Copie seu nome exatamente como está no código, incluindo maiúsculas. Habilitado permite usar o Script, mas a edição ainda precisa ser publicada e ativada para chegar à versão em execução.",
                    "Give the Script a display name that explains its task. The key identifies it in the project; it is not the function name.\n\nFor scope, choose where it works: Server on the server, Client Visual on the open screen. This changes the available functions and events.\n\nHandler is the function to call. Copy its name exactly from the code, including case. Enabled allows use of the Script, but the edit still needs publishing and activation to reach the running version.",
                    "Dele al Script un nombre visible que explique su tarea. La clave lo identifica en el proyecto; no es el nombre de la función.\n\nEn alcance, elija dónde trabaja: Server en el servidor, Client Visual en la pantalla abierta. Eso cambia las funciones y eventos disponibles.\n\nHandler es la función que se llama. Copie su nombre exactamente del código, incluidas mayúsculas. Habilitado permite usar el Script, pero la edición debe publicarse y activarse para llegar a la versión en ejecución."),
                LS(locale, "Escolha o gatilho pela necessidade", "Choose the trigger for the task", "Elija el disparador según la tarea",
                    "O gatilho é o acontecimento que chama a função. Escolha apenas o que atende à tarefa:\n\nInitialize chama ao iniciar a instância do Script. Pode acontecer novamente em outra ativação. Dispose é usado ao encerrá-la; mantenha a função curta.\n\nTagChanged reage à mudança do TAG escolhido na entrada. Ler outros TAGs dentro da função não os transforma em gatilhos. Timer chama em intervalos: informe milissegundos e respeite o mínimo mostrado. O produto cuida da repetição; não escreva um laço de espera.\n\nServerRuntimeEvent reage ao evento de Runtime associado. Seu payload é o conjunto de dados entregue à função; confira o formato do evento real. No Client Visual, objectInteraction recebe Click ou interações de ponteiro associadas no painel Eventos do objeto.",
                    "The trigger is the occurrence that calls the function. Choose the one that fits the task:\n\nInitialize calls when the Script instance starts. It may happen again after another activation. Dispose is used when it ends; keep the function short.\n\nTagChanged responds to a change in the TAG selected in the entry point. Reading other TAGs inside the function does not make them triggers. Timer calls at intervals: enter milliseconds and respect the displayed minimum. The product handles repetition; do not write a waiting loop.\n\nServerRuntimeEvent responds to the associated Runtime event. Its payload is the data delivered to the function; check the actual event format. In Client Visual, objectInteraction receives Click or pointer interactions associated in the object’s Events panel.",
                    "El disparador es el acontecimiento que llama la función. Elija el adecuado para la tarea:\n\nInitialize llama al iniciar la instancia del Script. Puede ocurrir de nuevo en otra activación. Dispose se usa al terminarla; mantenga la función corta.\n\nTagChanged responde al cambio del TAG elegido en la entrada. Leer otros TAGs dentro de la función no los convierte en disparadores. Timer llama a intervalos: indique milisegundos y respete el mínimo mostrado. El producto repite la llamada; no escriba un bucle de espera.\n\nServerRuntimeEvent responde al evento de Runtime asociado. Su payload es el conjunto de datos entregado a la función; compruebe el formato del evento real. En Client Visual, objectInteraction recibe Click o interacciones de puntero asociadas en Eventos del objeto."),
                LS(locale, "Declare cada referência usada", "Declare each reference used", "Declare cada referencia usada",
                    "Uma dependência é o recurso que você declara para o Script usar. Por exemplo, declare o TAG de pressão que ele vai ler e a memória em que vai guardar o cálculo. Escrever esses nomes no código não cria as declarações.\n\nUse o Object Browser, o seletor de referências do projeto. Confira o recurso e o tipo: TAG de processo, ServerMemoryTag, evento ou comando. O caminho legível fica ligado à identidade estável do recurso; esse vínculo é chamado binding. Você não precisa adivinhar um ID.\n\nPara gravar memória do servidor, escolha um destino ServerMemoryTag. Para escrita de processo, confira se o TAG aceita escrita e se há permissão. Para um comando, declare o comando específico. Declarar o recurso não concede uma permissão que a conta não possui.",
                    "A dependency is a resource you declare for the Script to use. For example, declare the pressure TAG it reads and the memory that stores its calculation. Writing those names in code does not create declarations.\n\nUse Object Browser, the project reference picker. Check the resource and type: process TAG, ServerMemoryTag, event or command. The readable path connects to the resource’s stable identity; that connection is called a binding. You do not need to guess an ID.\n\nTo write server memory, choose a ServerMemoryTag target. For a process write, check that the TAG is writable and permission exists. For a command, declare the specific command. Declaring a resource does not grant a permission the account lacks.",
                    "Una dependencia es el recurso que declara para que lo use el Script. Por ejemplo, declare el TAG de presión que lee y la memoria donde guarda el cálculo. Escribir esos nombres en el código no crea declaraciones.\n\nUse Object Browser, el selector de referencias del proyecto. Compruebe recurso y tipo: TAG de proceso, ServerMemoryTag, evento o comando. La ruta legible queda vinculada a la identidad estable del recurso; ese vínculo se llama binding. No necesita adivinar un ID.\n\nPara escribir memoria del servidor, elija un destino ServerMemoryTag. Para escritura de proceso, compruebe que el TAG admite escritura y que existe permiso. Para un comando, declare el comando específico. Declarar el recurso no concede un permiso que la cuenta no tiene."),
                LS(locale, "Confira se a ligação está completa", "Check the complete connection", "Compruebe la conexión completa",
                    "1. Compare o nome da função com o campo Handler. 2. Confirme escopo e evento. 3. Para TagChanged, confira o TAG disparador; para Timer, intervalo; para evento de Runtime, origem e payload. 4. Revise dependências e bindings. 5. Valide e faça o teste disponível. 6. Salve e siga publicação/ativação; confira os diagnósticos da revisão em execução. Se nada acontecer, primeiro confirme o evento e a revisão, antes de modificar o cálculo.",
                    "1. Compare the function name with Handler. 2. Confirm scope and event. 3. For TagChanged check the triggering TAG; for Timer its interval; for Runtime events the source and payload. 4. Review dependencies and bindings. 5. Validate and use the available test. 6. Save and follow publish/activate; check the running revision's diagnostics. If nothing happens, first check event and revision before changing the calculation.",
                    "1. Compare función y Handler. 2. Confirme alcance y evento. 3. En TagChanged compruebe el TAG disparador; en Timer el intervalo; en eventos Runtime origen y payload. 4. Revise dependencias y bindings. 5. Valide y use la prueba disponible. 6. Guarde y siga publicación/activación; compruebe diagnósticos de la revisión ejecutada. Si no ocurre nada, verifique evento y revisión antes de cambiar el cálculo.")
            ], "scripts.engineering", "engineering.object-browser", "scripts.server-syntax", "visual.events");

        yield return LT(locale, "scripts.server-recipes", "scripts",
            Tx("Server Script: receitas com resultado explicado", "Server Script: recipes with explained results", "Server Script: recetas con resultado explicado"),
            Tx("Adapte exemplos pequenos para calcular, guardar estado e publicar uma leitura sem inventar sua qualidade.", "Adapt small examples to calculate, retain state and publish a reading without inventing its quality.", "Adapte ejemplos pequeños para calcular, conservar estado y publicar sin inventar calidad."),
            [
                LS(locale, "Exemplo: converter uma grandeza calculada", "Example: calculate a converted quantity", "Ejemplo: calcular una magnitud convertida",
                    "Considere um TAG de vazão em litros por segundo e um ServerMemoryTag de saída em m³/h. Declare ambos e use Timer ou TagChanged conforme a aplicação. Multiplicar por 3.6 faz a conversão; apenas mudar o rótulo da unidade na tela não faria isso. O exemplo só grava se houver valor e não certifica qualidade/frescor da origem.",
                    "Assume a flow TAG in liters per second and a ServerMemoryTag output in m³/h. Declare both and use Timer or TagChanged as appropriate. Multiplying by 3.6 performs the conversion; changing a screen's unit label would not. The example writes only when a value exists and does not certify source quality/freshness.",
                    "Suponga un TAG de caudal en litros por segundo y una salida ServerMemoryTag en m³/h. Declare ambos y use Timer o TagChanged. Multiplicar por 3.6 convierte; cambiar la etiqueta de unidad no lo haría. Solo escribe si hay valor y no certifica calidad/vigencia del origen.",
                    HelpExample("server-convert")),
                LS(locale, "Exemplo: dois limites para evitar oscilação", "Example: two limits to avoid oscillation", "Ejemplo: dos límites para evitar oscilación",
                    "Um estado booleano retentivo pode ligar acima de 8 e desligar abaixo de 7, permanecendo como estava entre os dois limites. Isso é histerese. Declare pressão e memória de estado e use TagChanged na pressão. Os números são demonstrativos: escolha valores compatíveis com o processo. Se precisa de um alarme com reconhecimento e histórico de estado, configure Alarm em vez de assumir que esta variável o substitui.",
                    "A retained boolean can turn on above 8 and off below 7, keeping its state between the limits. This is hysteresis. Declare pressure and state memory and use TagChanged on pressure. Numbers are illustrative: choose values appropriate to the process. If you need an alarm with acknowledgement and state history, configure Alarm rather than treating this variable as its replacement.",
                    "Un booleano retentivo puede activarse por encima de 8 y desactivarse por debajo de 7, conservando estado entre límites. Es histéresis. Declare presión y memoria y use TagChanged en presión. Los números son ilustrativos: elija límites del proceso. Si necesita alarma con reconocimiento e histórico, configure Alarm; esta variable no lo sustituye.",
                    HelpExample("server-hysteresis")),
                LS(locale, "Exemplo: amostra com qualidade conservadora", "Example: a sample with conservative quality", "Ejemplo: muestra con calidad conservadora",
                    "`read_tag` devolve só o valor no Server. Não permite deduzir a qualidade ou o timestamp de origem. Se a aplicação ainda não comprovou a confiabilidade da leitura, publicar Uncertain mantém essa limitação visível. `publish_server_memory_sample` recebe a referência, o valor e uma TagQuality suportada. O destino precisa ser ServerMemoryTag declarado.",
                    "Server `read_tag` returns only the value. It does not establish source quality or timestamp. If the application has not established reading reliability, publishing Uncertain keeps that limitation visible. `publish_server_memory_sample` receives the reference, value and a supported TagQuality. Its target must be a declared ServerMemoryTag.",
                    "`read_tag` de Server devuelve solo el valor. No establece calidad ni timestamp de origen. Si la aplicación no ha demostrado fiabilidad, publicar Uncertain mantiene visible esa limitación. `publish_server_memory_sample` recibe referencia, valor y TagQuality admitida. El destino debe ser ServerMemoryTag declarado.",
                    HelpExample("server-sample")),
                LS(locale, "O que conferir em cada receita", "What to check in each recipe", "Qué comprobar en cada receta",
                    "Faça tentativas com valor normal, limite, ausência e tipo incorreto; confira o destino gravado. Os exemplos usam referências demonstrativas que você deve substituir pelo seletor do seu projeto. Uma memória com último valor não prova que o dado continua atual. Para eventos operacionais e comandos, consulte os guias relacionados e configure as dependências correspondentes.",
                    "Try normal, boundary, missing and wrong-type values and check the written target. Examples use illustrative references that you must replace through your project's picker. Last-value memory does not prove that the data remains current. For operational events and commands, use the related guides and configure their dependencies.",
                    "Pruebe valores normales, límites, ausencia y tipos incorrectos y compruebe el destino escrito. Sustituya las referencias demostrativas mediante el selector del proyecto. Una memoria con último valor no prueba que siga vigente. Para eventos y comandos, consulte las guías y configure sus dependencias.")
            ], "scripts.server-syntax", "scripts.server", "sources.internal-memory", "operational-events.overview", "scripts.commands-feedback");

        yield return LT(locale, "scripts.commands-feedback", "scripts",
            Tx("Escritas e comandos: parâmetros, permissão e retorno", "Writes and commands: parameters, permission and feedback", "Escrituras y comandos: parámetros, permiso y resultado"),
            Tx("Diferencie pedir um valor, solicitar um comando e confirmar o que aconteceu no equipamento.", "Distinguish writing a value, requesting a command and confirming what happened in the equipment.", "Distinga escribir un valor, solicitar un comando y confirmar qué ocurrió en el equipo."),
            [
                LS(locale, "Escolha a operação certa", "Choose the right operation", "Elija la operación adecuada",
                    "Primeiro defina o que o operador quer fazer. Mudar um valor, como uma consigna, é diferente de solicitar uma operação, como um comando de equipamento.\n\nNo Server, `write_tag(referência, valor)` pede a escrita de um valor compatível num TAG declarado e gravável. Rich Command pede uma operação com os parâmetros definidos para aquele comando. Declare o destino e confira sua unidade antes de permitir uma ação real.\n\nAs permissões também são distintas: ProcessValueWrite permite a escrita de valor; CommandExecute permite o comando. Uma não substitui a outra. A sessão View Only continua limitada à visualização, mesmo que a conta tenha outras permissões.",
                    "First define what the operator wants to do. Changing a value, such as a setpoint, differs from requesting an operation, such as an equipment command.\n\nOn Server, `write_tag(reference, value)` requests a compatible value write to a declared writable TAG. Rich Command requests an operation with the parameters defined for that command. Declare the target and check its unit before allowing a real action.\n\nPermissions differ too: ProcessValueWrite allows value writes; CommandExecute allows commands. Neither replaces the other. A View Only session remains limited to viewing even if the account has other permissions.",
                    "Primero defina qué quiere hacer el operador. Cambiar un valor, como una consigna, es distinto de solicitar una operación, como un comando de equipo.\n\nEn Server, `write_tag(referencia, valor)` solicita escribir un valor compatible en un TAG declarado y escribible. Rich Command solicita una operación con los parámetros definidos para ese comando. Declare el destino y compruebe su unidad antes de permitir una acción real.\n\nLos permisos también son distintos: ProcessValueWrite permite escribir valores; CommandExecute permite comandos. Ninguno sustituye al otro. Una sesión View Only sigue limitada a visualización aunque la cuenta tenga otros permisos."),
                LS(locale, "Parâmetros e resultado de Rich Command", "Rich Command parameters and result", "Parámetros y resultado Rich Command",
                    "A chamada Server é `invoke_rich_command(command_id, parameters)`. `command_id` identifica o comando declarado. `parameters` reúne os nomes e valores que esse comando espera, em um dicionário; cada valor deve ser de um tipo simples compatível. Adapte o exemplo completo do guia Server Script ao comando real selecionado.\n\nO retorno traz `outcome`, que informa o resultado conhecido da solicitação. Leia antes de repetir:\n\nRejected: a solicitação foi recusada. Accepted: foi aceita, mas isso não confirma que o equipamento concluiu a ação. Completed: a operação informou conclusão.\n\nFailed e TimedOut pedem diagnóstico da falha ou do tempo excedido. Unknown significa que o resultado não é conhecido; a ação pode ter ocorrido. Confira o estado real antes de outra tentativa e nunca repita automaticamente um comando Unknown.",
                    "The Server call is `invoke_rich_command(command_id, parameters)`. `command_id` identifies the declared command. `parameters` is a dictionary containing the names and values that command expects; each value must have a compatible simple type. Adapt the full Server Script example to the actual selected command.\n\nThe response includes `outcome`, the known result of the request. Read it before repeating:\n\nRejected: the request was refused. Accepted: it was accepted, but equipment completion is not confirmed. Completed: the operation reported completion.\n\nFailed and TimedOut require diagnosis of the failure or elapsed time. Unknown means the result is not known; the action may have occurred. Check actual state before another attempt and never automatically repeat an Unknown command.",
                    "La llamada Server es `invoke_rich_command(command_id, parameters)`. `command_id` identifica el comando declarado. `parameters` es un diccionario con los nombres y valores que espera ese comando; cada valor debe tener un tipo simple compatible. Adapte el ejemplo completo de Server Script al comando real seleccionado.\n\nLa respuesta incluye `outcome`, el resultado conocido de la solicitud. Léalo antes de repetir:\n\nRejected: solicitud rechazada. Accepted: aceptada, pero sin confirmar que el equipo terminó la acción. Completed: la operación informó finalización.\n\nFailed y TimedOut requieren diagnosticar el fallo o el tiempo excedido. Unknown significa resultado desconocido; la acción puede haber ocurrido. Compruebe el estado real antes de otro intento y nunca repita automáticamente un comando Unknown."),
                LS(locale, "Separe intenção de realimentação", "Separate intent from feedback", "Separe intención de realimentación",
                    "Mostre separadamente o pedido e o estado do equipamento. Um botão pode indicar pedido enviado enquanto o motor ainda está parado. Para mostrar se o motor realmente funciona, use a variável de retorno do processo, chamada realimentação.\n\nDepois de tempo excedido ou resultado desconhecido, confira essa realimentação e os registros antes de outra ação. Na Pré-visualização de Engenharia, algumas chamadas podem ser bloqueadas para proteger o processo. Leia o motivo e confira o ambiente de teste antes de concluir que há defeito no comando.",
                    "Show the request separately from equipment state. A button may indicate request sent while the motor is still stopped. To show whether the motor actually runs, use its process return variable, called feedback.\n\nAfter a timeout or unknown result, check that feedback and the records before another action. Engineering Preview may block some calls to protect the process. Read the reason and check the test environment before concluding the command is defective.",
                    "Muestre por separado la solicitud y el estado del equipo. Un botón puede indicar solicitud enviada mientras el motor sigue parado. Para mostrar si realmente funciona, use la variable de retorno del proceso, llamada realimentación.\n\nTras tiempo excedido o resultado desconocido, compruebe esa realimentación y los registros antes de otra acción. La Vista previa de Ingeniería puede bloquear llamadas para proteger el proceso. Lea el motivo y compruebe el entorno de prueba antes de concluir que el comando tiene un defecto.")
            ], "scripts.server", "bindings-commands.overview", "tags.writeability", "runtime.session-classes", "visual.events");

        yield return LT(locale, "scripts.client-api", "scripts",
            Tx("Client Visual: referência das funções", "Client Visual: function reference", "Client Visual: referencia de funciones"),
            Tx("Consulte assinatura, argumentos e finalidade antes de adaptar um exemplo.", "Check signature, arguments and purpose before adapting an example.", "Consulte firma, argumentos y finalidad antes de adaptar un ejemplo."),
            [
                LS(locale, "Importar e aguardar a resposta", "Import and await the response", "Importar y esperar la respuesta",
                    "Importe apenas as funções usadas com `from elite_scada import ...`. Nas chamadas abaixo, use `await` dentro de um handler `async def`. Referências são textos que apontam para recursos reais: selecione e declare TAGs no Script. O destino visual precisa pertencer à instância atual. Os exemplos desta tabela mostram sintaxe de chamada; os guias de receitas mostram a configuração e o código completo.",
                    "Import only used functions with `from elite_scada import ...`. Use `await` inside an `async def` handler for these calls. References are strings identifying actual resources: select and declare TAGs on the Script. A visual target must belong to the current instance. This table shows call syntax; recipe guides provide setup and complete code.",
                    "Importe solo funciones usadas con `from elite_scada import ...`. Use `await` dentro de `async def`. Las referencias son textos de recursos reales: seleccione y declare TAGs en el Script. El destino visual debe pertenecer a la instancia actual. La tabla muestra sintaxis; las recetas incluyen configuración y código completo."),
                new ContextualHelpSection(Pick(locale, "Funções, argumentos e uso", "Functions, arguments and use", "Funciones, argumentos y uso"), Pick(locale,
                    "Uma leitura e uma escrita têm consequências diferentes. Escolha a operação pela finalidade e mantenha as permissões da sessão em consideração.",
                    "Reading and writing have different consequences. Choose the operation by its purpose and account for session permissions.",
                    "Leer y escribir tienen consecuencias distintas. Elija según finalidad y considere permisos de sesión."), Fields:
                [
                    IF(locale, "tag_read", "tag_read(reference)", "tag_read(reference)", "tag_read(reference)",
                        "Lê um TAG declarado. reference é caminho vinculado ou identidade declarada. Retorna objeto com value, quality, timestamp e source; acesse campos com ponto.",
                        "Reads a declared TAG. reference is a bound path or declared identity. Returns an object with value, quality, timestamp and source; access fields with dots.",
                        "Lee un TAG declarado. reference es ruta vinculada o identidad declarada. Devuelve objeto con value, quality, timestamp y source; acceda con punto.",
                        "sample = await tag_read(\"Plant.Pump.Current\")", "sample = await tag_read(\"Plant.Pump.Current\")", "sample = await tag_read(\"Plant.Pump.Current\")"),
                    IF(locale, "tag_write", "tag_write(reference, value)", "tag_write(reference, value)", "tag_write(reference, value)",
                        "Solicita escrita de número finito, texto ou booleano em TAG declarado e gravável. Tipo, permissão e classe de sessão são verificados; depois confira realimentação do processo.",
                        "Requests a finite number, text or boolean write to a declared writable TAG. Type, permission and session class are checked; then check process feedback.",
                        "Solicita escritura de número finito, texto o booleano en TAG declarado y escribible. Se verifica tipo, permiso y clase; después compruebe feedback.",
                        "await tag_write(\"Plant.Pump.Setpoint\", 25)", "await tag_write(\"Plant.Pump.Setpoint\", 25)", "await tag_write(\"Plant.Pump.Setpoint\", 25)"),
                    IF(locale, "client_memory_read", "client_memory_read(reference)", "client_memory_read(reference)", "client_memory_read(reference)",
                        "Lê a referência de memória deste cliente. A referência deve existir no modelo Client Memory; não consulta Server Memory nem outro cliente.",
                        "Reads a memory reference in this client. It must exist in the Client Memory model; it does not read Server Memory or another client.",
                        "Lee una referencia de memoria de este cliente. Debe existir en Client Memory; no lee Server Memory ni otro cliente.",
                        "value = await client_memory_read(\"UI.LastPressure\")", "value = await client_memory_read(\"UI.LastPressure\")", "value = await client_memory_read(\"UI.LastPressure\")"),
                    IF(locale, "client_memory_write", "client_memory_write(reference, value)", "client_memory_write(reference, value)", "client_memory_write(reference, value)",
                        "Grava valor serializável na memória local configurada e retorna a leitura resultante. Não cria histórico nem sincroniza estações.",
                        "Writes a serializable value to configured local memory and returns the resulting reading. It creates no history and does not synchronize stations.",
                        "Escribe un valor serializable en memoria local configurada y devuelve la lectura resultante. No crea histórico ni sincroniza estaciones.",
                        "await client_memory_write(\"UI.LastPressure\", 4.2)", "await client_memory_write(\"UI.LastPressure\", 4.2)", "await client_memory_write(\"UI.LastPressure\", 4.2)"),
                    IF(locale, "visual_property_read", "visual_property_read(target, property)", "visual_property_read(target, property)", "visual_property_read(target, property)",
                        "Lê uma propriedade registrada no objeto visual atual. target identifica o objeto e property é a chave técnica, não o rótulo traduzido do Inspetor.",
                        "Reads a registered property on the current visual object. target identifies the object and property is its technical key, not the Inspector's translated label.",
                        "Lee una propiedad registrada del objeto actual. target identifica el objeto y property es la clave técnica, no la etiqueta traducida del Inspector.",
                        "value = await visual_property_read(event.visualObjectId, \"opacity\")", "value = await visual_property_read(event.visualObjectId, \"opacity\")", "value = await visual_property_read(event.visualObjectId, \"opacity\")"),
                    IF(locale, "visual_property_write", "visual_property_write(target, property, value)", "visual_property_write(target, property, value)", "visual_property_write(target, property, value)",
                        "Solicita um override visual local de propriedade gravável. O tipo e os limites da propriedade são validados. Não salva o desenho e não grava um TAG.",
                        "Requests a local override of a writable visual property. Its type and limits are validated. It does not save the drawing or write a TAG.",
                        "Solicita un override visual local de propiedad escribible. Se validan tipo y límites. No guarda el dibujo ni escribe un TAG.",
                        "await visual_property_write(event.visualObjectId, \"opacity\", 0.7)", "await visual_property_write(event.visualObjectId, \"opacity\", 0.7)", "await visual_property_write(event.visualObjectId, \"opacity\", 0.7)"),
                    IF(locale, "visual_property_clear", "visual_property_clear(target, property)", "visual_property_clear(target, property)", "visual_property_clear(target, property)",
                        "Retira o override de Script para voltar à resolução normal da propriedade. Não apaga o objeto nem seu vínculo persistido.",
                        "Removes the Script override so normal property resolution resumes. It does not delete the object or its persisted binding.",
                        "Retira el override del Script para recuperar la resolución normal. No borra el objeto ni su vínculo persistido.",
                        "await visual_property_clear(event.visualObjectId, \"opacity\")", "await visual_property_clear(event.visualObjectId, \"opacity\")", "await visual_property_clear(event.visualObjectId, \"opacity\")"),
                    IF(locale, "visual_tween_request", "visual_tween_request(arguments)", "visual_tween_request(arguments)", "visual_tween_request(arguments)",
                        "Solicita transição de uma propriedade animável. O dicionário exige targetReference, propertyKey, targetValue e durationMs. Não anime booleanos; confira tipo e limites no guia do objeto. Opções adicionais são validadas pelo serviço visual.",
                        "Requests a transition for an animatable property. The dictionary requires targetReference, propertyKey, targetValue and durationMs. Do not animate booleans; check type and limits in the object guide. The visual service validates additional options.",
                        "Solicita transición de propiedad animable. El diccionario exige targetReference, propertyKey, targetValue y durationMs. No anime booleanos; consulte tipo y límites del objeto. El servicio valida opciones adicionales.",
                        "await visual_tween_request({\"targetReference\": event.visualObjectId, \"propertyKey\": \"opacity\", \"targetValue\": 0.7, \"durationMs\": 300})", "await visual_tween_request({\"targetReference\": event.visualObjectId, \"propertyKey\": \"opacity\", \"targetValue\": 0.7, \"durationMs\": 300})", "await visual_tween_request({\"targetReference\": event.visualObjectId, \"propertyKey\": \"opacity\", \"targetValue\": 0.7, \"durationMs\": 300})")
                ])
            ], "scripts.client-recipes", "scripts.client-visual", "visual.properties", "memory.client", "scripts.commands-feedback");

        yield return LT(locale, "scripts.client-recipes", "scripts",
            Tx("Client Visual: interação e aparência com exemplos", "Client Visual: interaction and appearance examples", "Client Visual: interacción y aspecto con ejemplos"),
            Tx("Ligue um handler ao objeto e use leituras confiáveis para uma reação visual local.", "Connect a handler to its object and use reliable readings for a local visual response.", "Vincule un handler al objeto y use lecturas fiables para una reacción visual local."),
            [
                LS(locale, "Prepare o handler e o objeto", "Prepare the handler and object", "Prepare handler y objeto",
                    "Estes exemplos reagem à interação do operador com um objeto. Comece em uma tela de teste:\n\n1. Crie um Script Client Visual e uma entrada objectInteraction. Essa entrada permite receber a interação associada ao objeto.\n2. Escreva uma função com a forma `async def nome(event)`. Handler é o nome dessa função. `event` traz os dados da interação, como o objeto que a recebeu.\n3. Selecione o objeto na tela. No painel Eventos, escolha a interação, o Script e o nome exato da função.\n4. Declare as referências usadas no exemplo e valide.\n\n`async` permite esperar chamadas do produto; `await` espera a resposta antes de continuar. Isso não cria uma repetição contínua. Os exemplos abaixo atuam no próprio objeto que recebeu o evento.",
                    "These examples respond to the operator’s interaction with an object. Start on a test screen:\n\n1. Create a Client Visual Script and an objectInteraction entry point. It receives the interaction associated with the object.\n2. Write a function in the form `async def name(event)`. Handler is that function’s name. `event` carries interaction data, including the receiving object.\n3. Select the object on the screen. In Events, choose the interaction, Script and exact function name.\n4. Declare the references used by the example and validate.\n\n`async` allows waiting for product calls; `await` waits for a response before continuing. It does not create continuous repetition. The examples below act on the object that received the event.",
                    "Estos ejemplos responden a la interacción del operador con un objeto. Empiece en una pantalla de prueba:\n\n1. Cree un Script Client Visual y una entrada objectInteraction. Recibe la interacción asociada al objeto.\n2. Escriba una función con la forma `async def nombre(event)`. Handler es el nombre de esa función. `event` trae los datos de interacción, incluido el objeto que la recibió.\n3. Seleccione el objeto en la pantalla. En Eventos, elija interacción, Script y nombre exacto de función.\n4. Declare las referencias del ejemplo y valide.\n\n`async` permite esperar llamadas del producto; `await` espera una respuesta antes de continuar. No crea repetición continua. Los ejemplos siguientes actúan sobre el objeto que recibió el evento."),
                LS(locale, "Como acessar os campos retornados", "How to access returned fields", "Cómo acceder a los campos devueltos",
                    "Uma leitura do Client Visual vem com mais que o número: `value` é o valor e `quality` informa a qualidade. Depois de `sample = await tag_read(...)`, use `sample.value` e `sample.quality`. O ponto escolhe um campo dessa resposta. No evento, `event.visualObjectId` identifica o objeto que recebeu a interação.\n\nEssas respostas são objetos do produto, não dicionários Python comuns. Por isso, `sample[\"quality\"]` causa erro de tipo neste Runtime. Um dicionário criado por você continua usando colchetes. ServerRuntimeEvent tem outro formato; consulte esse evento antes de adaptar código entre os dois escopos.",
                    "A Client Visual reading contains more than the number: `value` is the value and `quality` describes its quality. After `sample = await tag_read(...)`, use `sample.value` and `sample.quality`. The dot selects a field in the response. In the event, `event.visualObjectId` identifies the object that received the interaction.\n\nThese responses are product objects, not ordinary Python dictionaries. That is why `sample[\"quality\"]` causes a type error in this Runtime. A dictionary you create still uses brackets. ServerRuntimeEvent has a different format; consult that event before adapting code between scopes.",
                    "Una lectura de Client Visual contiene más que el número: `value` es el valor y `quality` describe su calidad. Tras `sample = await tag_read(...)`, use `sample.value` y `sample.quality`. El punto elige un campo de la respuesta. En el evento, `event.visualObjectId` identifica el objeto que recibió la interacción.\n\nEstas respuestas son objetos del producto, no diccionarios Python comunes. Por eso, `sample[\"quality\"]` causa error de tipo en este Runtime. Un diccionario creado por usted sigue usando corchetes. ServerRuntimeEvent tiene otro formato; consulte ese evento antes de adaptar código entre alcances."),
                LS(locale, "Exemplo: cor baseada em duas leituras", "Example: color based on two readings", "Ejemplo: color basado en dos lecturas",
                    "Associe on_click ao Click de um Retângulo e declare os dois TAGs. O cliente recebe valor e qualidade. Só compara quando ambos estão Good; se não estiverem, usa cinza para que indisponibilidade não pareça condição normal. `visual_property_write` recebe alvo, chave da propriedade e valor. fillColor precisa existir no tipo do objeto; em um Botão, por exemplo, o fundo usa backgroundColor.",
                    "Associate on_click with a Rectangle's Click and declare both TAGs. The client receives value and quality. It compares only when both are Good; otherwise it uses gray so unavailability does not look normal. `visual_property_write` receives target, property key and value. fillColor must exist for the object type; a Button background uses backgroundColor instead.",
                    "Asocie on_click al Click de un Rectángulo y declare ambos TAGs. El cliente recibe valor y calidad. Compara solo cuando ambos son Good; en otro caso usa gris para no mostrar ausencia como normal. `visual_property_write` recibe destino, clave y valor. fillColor debe existir en el tipo; un Botón usa backgroundColor para el fondo.",
                    HelpExample("client-compare")),
                LS(locale, "Exemplo: realce ao apontar e restauração ao sair", "Example: pointer highlight and restore", "Ejemplo: resaltar al apuntar y restaurar al salir",
                    "Associe on_enter a Pointer enters object e on_leave a Pointer leaves object. O primeiro handler reduz a opacidade do próprio objeto. O segundo remove o override de Script, permitindo voltar ao valor definido pelo desenho/vínculo. Isso não salva uma nova configuração do objeto. O alvo precisa pertencer à instância visual atual; não use o ID de um objeto de outra tela.",
                    "Associate on_enter with Pointer enters object and on_leave with Pointer leaves object. The first handler reduces this object's opacity. The second removes its Script override so the drawing/binding value can apply again. This does not save a new object configuration. The target must belong to the current visual instance; do not use an object ID from another screen.",
                    "Asocie on_enter a Pointer enters object y on_leave a Pointer leaves object. El primero reduce opacidad del objeto. El segundo retira el override del Script para volver al valor del dibujo/vínculo. No guarda una nueva configuración. El destino debe pertenecer a la instancia visual actual; no use un ID de otra pantalla.",
                    HelpExample("client-hover")),
                LS(locale, "Exemplo: guardar uma preferência local", "Example: keep a local preference", "Ejemplo: guardar una preferencia local",
                    "A Client Memory pertence a este cliente Runtime. Configure a referência UI.LastPressure conforme o modelo do projeto. O exemplo guarda a última leitura Good após Click. Outro cliente não recebe automaticamente esse valor; não use essa memória para coordenar lógica de processo entre estações.",
                    "Client Memory belongs to this Runtime client. Configure UI.LastPressure according to your project model. This example stores the last Good reading after Click. Other clients do not automatically receive it; do not use this memory to coordinate process logic across stations.",
                    "Client Memory pertenece a este cliente Runtime. Configure UI.LastPressure según el modelo del proyecto. El ejemplo guarda la última lectura Good tras Click. Otros clientes no la reciben automáticamente; no use esta memoria para coordinar proceso entre estaciones.",
                    HelpExample("client-memory")),
                LS(locale, "Quando o resultado não aparece", "When the result does not appear", "Cuando no aparece el resultado",
                    "Confirme evento, nome do handler e revisão ativa. Para leitura negada, confira a dependência e a permissão. Para propriedade recusada, abra o tópico do tipo de objeto e consulte a chave, o tipo e os limites; não basta que uma propriedade exista em outro objeto. Mudanças locais desaparecem conforme a vida da instância e não alteram o desenho persistido. A Pré-visualização de Engenharia pode bloquear escrita de TAG de processo.",
                    "Check event, handler name and active revision. For denied reads, check dependency and permission. For rejected properties, open the object type's topic and check key, type and limits; a property existing on another object is insufficient. Local changes follow the instance lifetime and do not alter the persisted drawing. Engineering Preview can block process TAG writes.",
                    "Compruebe evento, handler y revisión activa. Si se deniega lectura, compruebe dependencia y permiso. Si se rechaza una propiedad, consulte clave, tipo y límites del objeto; no basta que exista en otro tipo. Los cambios locales siguen la vida de la instancia y no cambian el dibujo persistido. Vista previa puede bloquear escritura de proceso.")
            ], "scripts.client-visual", "visual.events", "visual.object.core.rectangle", "visual.object.core.button", "memory.client", "scripts.python-validation");
